PREFIX : <https://w3id.org/rastro/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?name WHERE {
  {
    SELECT ?s ?name (COUNT(DISTINCT ?tr) AS ?n) WHERE {
      ?tr a :Trial ; :status ?st ; :sponsor ?s ; :condition ?c .
      FILTER(?st IN ("TERMINATED", "WITHDRAWN"))
      ?s :industry true ; :name ?name .
      ?c :within ?m . ?m rdfs:label "Lung Neoplasms"@en .
    } GROUP BY ?s ?name
  }
} ORDER BY DESC(?n) LIMIT 3
